$st = $conn->prepare("INSERT INTO request_types
    (code, name_ar, owner_dept, submitter, receiver, approval_chain, sla_hours, deliverable, source_ref, status, display_order)
    VALUES (?,?,?,?,?,?,?,?,?,?,?)
    ON DUPLICATE KEY UPDATE name_ar=VALUES(name_ar), owner_dept=VALUES(owner_dept), submitter=VALUES(submitter),
      receiver=VALUES(receiver), approval_chain=VALUES(approval_chain), sla_hours=VALUES(sla_hours),
      deliverable=VALUES(deliverable), source_ref=VALUES(source_ref), status=VALUES(status), display_order=VALUES(display_order)");
$n = 0; $ord = 0;
foreach ($TYPES as $t) {
    $ord += 10;
    $st->bind_param('ssssssisssi', $t[0], $t[1], $t[2], $t[3], $t[4], $t[5], $t[6], $t[7], $t[8], $t[9], $ord);
    if ($st->execute()) { $n++; } else { fwrite(STDOUT, "✘ {$t[0]}: {$st->error}\n"); }
}
$st->close();
fwrite(STDOUT, "✔ أنواع الطلبات: {$n}/" . count($TYPES) . "\n");

