$st = $conn->prepare("INSERT INTO request_routes (item_kind, trigger_key, rule_text, receiver_dept, receiver_role, fallback_role, active)
    VALUES (?,?,?,?,?,?,1)
    ON DUPLICATE KEY UPDATE rule_text=VALUES(rule_text), receiver_dept=VALUES(receiver_dept),
      receiver_role=VALUES(receiver_role), fallback_role=VALUES(fallback_role), active=1");
$n = 0;
foreach ($ROUTES as $r) {
    $st->bind_param('ssssss', $r[0], $r[1], $r[2], $r[3], $r[4], $r[5]);
    if ($st->execute()) { $n++; } else { fwrite(STDOUT, "✘ قاعدة {$r[0]}: {$st->error}\n"); }
}
$st->close();
